const input=$json.body??$json;
const nd=input.negotiation_decision??{};
const decision=String(nd.decision||input.negotiation_decision_type||"").toLowerCase();
const mao=Number(nd.dynamic_mao??input.dynamic_mao??input.adjusted_mao??input.mao);
const counter=Number(nd.counteroffer_amount??input.counteroffer_amount);
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const validMao=Number.isFinite(mao)&&mao>0;
const validCounter=Number.isFinite(counter)&&counter>0;
const within=validMao&&validCounter&&counter<=mao;
const near=validMao&&validCounter&&counter>mao&&counter<=mao*1.10;
let action="needs_review",status="contract_decision_review_required",nextWorkflow="WF-126",reason="negotiation state requires human review",human=true;
if(blockers.length){action="blocked";status="negotiation_blocked";reason="active blockers present";}
else if(!validMao){action="needs_review";reason="dynamic MAO missing or invalid";}
else if(decision==="acceptance_ready"||decision==="counteroffer_within_mao"||within){
  action="contract_ready";status="contract_decision_ready";nextWorkflow="WF-201";reason="seller terms are within protected dynamic MAO";human=true;
}
else if(decision==="counteroffer_near_mao"||near){
  action="revised_offer";status="revised_offer_ready";nextWorkflow="WF-255";reason="counteroffer is above MAO but inside controlled negotiation band";human=true;
}
else if(decision==="counteroffer_above_mao"){
  action="walk_away_or_reengage";status="walk_away_review_required";nextWorkflow="WF-261";reason="counteroffer exceeds protected dynamic MAO";human=true;
}
else if(decision==="rejected"){
  action="reengage";status="reengagement_ready";nextWorkflow="WF-261";reason="seller rejected the offer";human=true;
}
else if(decision==="clarification_required"){
  action="clarify";status="clarification_required";nextWorkflow="WF-255";reason="seller response requires clarification";human=true;
}
else if(decision==="timeout_followup"){
  action="followup";status="followup_required";nextWorkflow="WF-290";reason="seller response timed out";human=false;
}
const guardrail=(action==="contract_ready"||action==="revised_offer")&&validCounter&&counter>mao?"HARD_BLOCK_ABOVE_DYNAMIC_MAO":"PASS";
const idempotencyKey=input.idempotency_key||`wf-293:${input.deal_id||"unknown"}:${input.dispatch_id||"none"}:${input.version||1}`;
return [{json:{...input,workflow:"WF-293",workflow_name:"Negotiation Decision → Revised Offer / Contract Decision Controller",status,contract_decision:{action,reason,dynamic_mao:validMao?mao:null,counteroffer_amount:validCounter?counter:null,within_dynamic_mao:within,near_dynamic_mao:near,guardrail},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"revised_offer_contract_decision",idempotency_key:idempotencyKey}}}];
